#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/capability_expansion_v4_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/capability_expansion.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_expansion_v4_patch.py"
python "$PREFIX/tmp/companyos_expansion_v4_patch.py"
rm -f "$PREFIX/tmp/companyos_expansion_v4_patch.py"

echo "" | base64 -d > tests/test_capability_expansion_staging_v4.py

echo "[1/5] Compile"
python -m py_compile companyos/runtime/capability_expansion.py tests/test_capability_expansion_staging_v4.py

echo "[2/5] Staging import test"
python -m unittest tests.test_capability_expansion_staging_v4 -v

echo "[3/5] Run expansion cycle"
scripts/companyos_expandctl once | tee .companyos_runtime/capability_expansion_v4_cycle.json

echo "[4/5] Commit/push"
git add companyos/runtime/capability_expansion.py tests/test_capability_expansion_staging_v4.py
git diff --cached --quiet || git commit -m "Fix isolated capability staging imports"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[5/5] Restart + verify"
scripts/companyosctl restart || true
sleep 8
echo "===== EXPANSION STATUS ====="
scripts/companyos_expandctl status || true
echo "===== INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CAPABILITY_EXPANSION_STAGING_IMPORT_V4=PASS"
